<?php
use GroupShop\Manager\{Stores,Catalog,ProductAdmin,Admin,SharedTaxonomies,Collections};
if (!defined('WP_CLI')||!WP_CLI||wp_get_environment_type()!=='local'||wp_parse_url(get_home_url(Stores::main_id()),PHP_URL_HOST)!=='localhost'||(int)wp_parse_url(get_home_url(Stores::main_id()),PHP_URL_PORT)!==18087) { throw new RuntimeException('Local isolated QA only'); }
wp_set_current_user(get_user_by('login','gsm-admin')->ID);
$checks=[];
$assert=static function ($ok,$name) use (&$checks): void { if (!$ok) { throw new RuntimeException('FAIL: '.$name); } $checks[]=$name; };
$throws=static function ($fn,$name) use ($assert): void { $failed=false; try { $fn(); } catch (Throwable $e) { $failed=true; } $assert($failed,$name); };
$main=Stores::main_id(); $a=(int)get_site_by_path(get_network()->domain,'/brand-a/')->blog_id; $b=(int)get_site_by_path(get_network()->domain,'/brand-b/')->blog_id;
$suffix=bin2hex(random_bytes(3));
$source=new WC_Product_Simple(); $source->set_name('QA Product Editor '.$suffix); $source->set_status('publish'); $source->set_regular_price('30'); $master=$source->save();
$pa=Catalog::publish($master,$a,Catalog::FIELDS); $pb=Catalog::publish($master,$b,Catalog::FIELDS);
Catalog::set_status($a,$pa,'publish','draft'); Catalog::set_status($b,$pb,'publish','draft');
Catalog::set_status($a,$pa,'draft','publish');
$assert(Stores::within($a,fn()=>get_post_status($pa))==='draft','Disable uses native draft status in the selected store');
$assert(get_post_status($master)==='publish'&&Stores::within($b,fn()=>get_post_status($pb))==='publish','Disabling does not change main or sibling editions');
$throws(fn()=>Catalog::set_status($a,$pa,'publish','publish'),'Stale quick action rejected');
Catalog::set_status($a,$pa,'publish','draft');
$throws(fn()=>Catalog::set_status($a,$pa,'trash','publish'),'Quick action cannot delete products');
$assert(Stores::within($a,fn()=>get_post_status($pa))==='publish','Quick re-enable publishes the selected edition');
$throws(fn()=>Catalog::save_edition($a,$pa,['category_ids'=>[]]),'Central editor rejects category writes');
$throws(fn()=>Catalog::save_edition($a,$pa,['tag_ids'=>[]]),'Central editor rejects tag writes');
Catalog::save_edition($a,$pa,['description'=>'<h2>Rich heading</h2><p><strong>Bold</strong> content<script>alert(1)</script></p>','short_description'=>'<ul><li>Feature</li></ul>']);
$desc=Stores::within($a,fn()=>wc_get_product($pa)->get_description('edit'));
$assert(str_contains($desc,'<h2>')&&str_contains($desc,'<strong>')&&!str_contains($desc,'<script>'),'Rich formatting persists and unsafe markup is stripped');
require_once ABSPATH.'wp-admin/includes/image.php';
$image=Stores::within($a,static function () use ($suffix): int { $f=wp_upload_bits('editor-'.$suffix.'.png',null,base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aWQAAAABJRU5ErkJggg==')); $id=wp_insert_attachment(['post_title'=>'Editor image '.$suffix,'post_mime_type'=>'image/png','post_status'=>'inherit'],$f['file']); wp_update_attachment_metadata($id,wp_generate_attachment_metadata($id,$f['file'])); return (int)$id; });
Catalog::save_edition($a,$pa,['image_ids'=>(string)$image]);
$assert(Stores::within($a,fn()=>(int)wc_get_product($pa)->get_image_id())===$image,'Selected local image saves through Woo CRUD');
$throws(fn()=>Catalog::save_edition($a,$pa,['image_ids'=>'99999999']),'Missing or foreign image rejected');
$attr=new WC_Product_Attribute(); $attr->set_name('Pack'); $attr->set_options(['Single','Double']); $attr->set_variation(true); $attr->set_visible(true);
$var=new WC_Product_Variable(); $var->set_name('QA Variants '.$suffix); $var->set_status('publish'); $var->set_attributes([$attr]); $vm=$var->save();
foreach (['Single','Double'] as $i=>$option) { $v=new WC_Product_Variation(); $v->set_parent_id($vm); $v->set_attributes(['pack'=>$option]); $v->set_regular_price((string)(40+20*$i)); $v->set_status('publish'); $v->save(); }
WC_Product_Variable::sync($vm);
$va=Catalog::publish($vm,$a,Catalog::FIELDS); $vb=Catalog::publish($vm,$b,Catalog::FIELDS);
$ids=Stores::within($a,fn()=>wc_get_product($va)->get_children()); $other=Stores::within($b,fn()=>wc_get_product($vb)->get_children());
Catalog::save_edition($a,$va,['name'=>'QA Variants Edited '.$suffix,'status'=>'publish','variations'=>[$ids[0]=>['regular_price'=>'49','sale_price'=>'39','status'=>'publish','image_ids'=>(string)$image,'description'=>'Single pack'],$ids[1]=>['regular_price'=>'79','sale_price'=>'','status'=>'private','image_ids'=>'']]]);
$assert(Stores::within($a,fn()=>wc_get_product($ids[0])->get_regular_price('edit'))==='49','Parent page saves variation prices');
$assert(Stores::within($a,fn()=>(int)wc_get_product($ids[0])->get_image_id('edit'))===$image,'Variation image saves from the local media library');
$assert(Stores::within($a,fn()=>wc_get_product($ids[1])->get_status())==='private','Disabling a variation uses native enabled status');
$assert(Stores::within($b,fn()=>wc_get_product($other[0])->get_regular_price('edit'))==='40','Variation edits do not change sibling store prices');
$assert(Stores::within($a,fn()=>wc_get_product($va)->get_price())==='39','Variable parent price is synchronized after child edits');
$before=Stores::within($a,fn()=>wc_get_product($va)->get_name());
$throws(fn()=>Catalog::save_edition($a,$va,['name'=>'Must not save','variations'=>[$ids[0]=>['regular_price'=>'50','sale_price'=>'35'],$ids[1]=>['regular_price'=>'10','sale_price'=>'20']]]),'An invalid later row rejects the whole submitted batch');
$assert(Stores::within($a,fn()=>wc_get_product($va)->get_name())===$before&&Stores::within($a,fn()=>wc_get_product($ids[0])->get_regular_price('edit'))==='49','Invalid batch leaves parent and earlier valid rows untouched');
$foreign=Stores::within($a,static function () use ($pa): int { $v=new WC_Product_Variation(); $v->set_parent_id($pa); $v->set_regular_price('9'); return $v->save(); });
$throws(fn()=>Catalog::save_edition($a,$va,['variations'=>[$foreign=>['regular_price'=>'1']]]),'Forged variation from another parent rejected');
$throws(fn()=>Catalog::save_edition($a,$pa,['regular_price'=>'12abc']),'Malformed prices rejected');
$throws(fn()=>Catalog::save_edition($a,$pa,['regular_price'=>'-1']),'Negative prices rejected');
$throws(fn()=>Catalog::save_edition($a,$pa,['name'=>'']),'Empty product name rejected');
$_GET=['page'=>'muti-storefront-plugin','tab'=>'products','store'=>$a]; ob_start(); ProductAdmin::render($a); $list=ob_get_clean();
$assert(str_contains($list,'gsm-product-thumb')&&!str_contains($list,'<th>库存</th>'),'List displays thumbnails without a stock column');
$assert(str_contains($list,'edition_status')&&str_contains($list,'expected_status'),'List includes nonce-protected scoped quick status actions');
$_GET['product']=$va; ob_start(); ProductAdmin::render($a); $html=ob_get_clean();
$assert(str_contains($html,'wp-gsm_description-wrap')&&str_contains($html,'wp-gsm_short_description-wrap'),'Editor uses native rich text for long and short descriptions');
$assert(!str_contains($html,'name="category_ids')&&!str_contains($html,'name="tag_ids'),'Product editor contains no classification inputs');
$assert(str_contains($html,'gsm-image-picker')&&!str_contains($html,'图片附件编号'),'Images have visual selectors instead of manual attachment fields');
$assert(str_contains($html,'Single')&&str_contains($html,'Double')&&str_contains($html,'variations['.$ids[1].'][regular_price]'),'Variation rows show specifications and include disabled children');
$assert(strpos($html,'gsm_product_complete')>strpos($html,'variations['),'Completeness marker follows all variation inputs');
$assert(get_current_blog_id()===$main,'Editor and failed operations restore main store context');
// More than one page remains safe under PHP input limits; unsubmitted rows are preserved.
Stores::within($a,static function () use ($va): void { for($i=0;$i<20;$i++) { $v=new WC_Product_Variation(); $v->set_parent_id($va); $v->set_attributes(['pack'=>'Extra '.($i+1)]); $v->set_regular_price('90'); $v->save(); } WC_Product_Variable::sync($va); });
$_GET['variation_page']=1; ob_start(); ProductAdmin::render($a); $first=ob_get_clean();
$_GET['variation_page']=2; ob_start(); ProductAdmin::render($a); $second=ob_get_clean();
$assert(substr_count($first,'data-price="regular_price"')===20&&substr_count($second,'data-price="regular_price"')===2,'Variations paginate in 20-row pages without losing disabled rows');
$scheduled=Stores::within($a,static function (): int { $p=new WC_Product_Simple(); $p->set_name('QA Scheduled'); $p->set_regular_price('5'); $p->set_date_created(time()+86400); $p->set_status('future'); return $p->save(); });
Catalog::set_status($a,$scheduled,'publish','future');
$assert(Stores::within($a,fn()=>get_post_status($scheduled))==='publish','Quick publish handles a previously scheduled native post');
$assert(Stores::within($a,fn()=>!wc_get_product($va)->get_manage_stock()&&wc_get_product($ids[0])->get_stock_status()==='instock'),'Unlimited stock policy remains intact');
$customer=get_users(['role'=>'customer','number'=>1,'blog_id'=>$a]);
if ($customer) { wp_set_current_user($customer[0]->ID); $throws(fn()=>Catalog::set_status($a,$pa,'draft','publish'),'Customer cannot manage store status'); $throws(fn()=>Catalog::save_edition($a,$pa,['name'=>'forbidden']),'Customer cannot edit products'); wp_set_current_user(get_user_by('login','gsm-admin')->ID); }
SharedTaxonomies::reconcile();
echo wp_json_encode(['version'=>GSM_VERSION,'passed'=>count($checks),'checks'=>$checks,'fixtures'=>['main'=>$main,'a'=>$a,'b'=>$b,'master'=>$master,'simple'=>$pa,'sibling'=>$pb,'variable'=>$va,'variations'=>$ids,'image'=>$image,'scheduled'=>$scheduled]],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)."\n";
